: 15, "missing": 0}, {"id": "h87", "parts": ["h87-t1", "h87-t2", "h87-t3"], "title": "Test 87", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h88", "parts": ["h88-t1", "h88-t2", "h88-t3"], "title": "Test 88", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h89", "parts": ["h89-t1", "h89-t2", "h89-t3"], "title": "Test 89", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h90", "parts": ["h90-t1", "h90-t2", "h90-t3"], "title": "Test 90", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h91", "parts": ["h91-t1", "h91-t2", "h91-t3"], "title": "Test 91", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h92", "parts": ["h92-t1", "h92-t2", "h92-t3"], "title": "Test 92", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h93", "parts": ["h93-t1", "h93-t2", "h93-t3"], "title": "Test 93", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h94", "parts": ["h94-t1", "h94-t2", "h94-t3"], "title": "Test 94", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h96", "parts": ["h96-t1", "h96-t2", "h96-t3"], "title": "Test 96", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h97", "parts": ["h97-t1", "h97-t2", "h97-t3"], "title": "Test 97", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h98", "parts": ["h98-t1", "h98-t2", "h98-t3"], "title": "Test 98", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h99", "parts": ["h99-t1", "h99-t2", "h99-t3"], "title": "Test 99", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h100", "parts": ["h100-t1", "h100-t2", "h100-t3"], "title": "Test 100", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h101", "parts": ["h101-t1", "h101-t2", "h101-t3"], "title": "Test 101", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}, {"id": "h102", "parts": ["h102-t1", "h102-t2", "h102-t3"], "title": "Test 102", "minutes": 0, "maxPoints": 0, "availablePoints": 15, "missing": 0}]'::jsonb, 781, true, 1)
