    ('lv3-11', 'Lesen', 'Übung 11', 0, 'Lesen Sie die Texte und die Aufgaben. Kreuzen Sie an: Richtig oder Falsch.', 'truefalse', '{"passages": [{"paragraphs": [{"t": "Die Volkshochschule zieht um.", "b": false}, {"t": "Unterricht erst wieder am 1.4.", "b": false}], "before": 0, "cap": "An der Volkshochschule"}, {"paragraphs": [{"t": "Ab sofort ist das Rauchen in allen Büroräumen verboten.", "b": true}], "before": 1, "cap": "Im Büro"}, {"paragraphs": [{"t": "Die Wohnung ist leider schon vermietet.", "b": false}, {"t": "Montag, 2. Januar", "b": false}, {"t": "Hans Krause, Vermieter", "b": false}], "before": 2, "cap": "An einer Wohnungstür"}, {"paragraphs": [{"t": "Liebe Mieter,", "b": false}, {"t": "die Firma Knorr macht am Dienstag Reparaturarbeiten im Haus.", "b": false}, {"t": "Die Firma muss an diesem Tag in alle Wohnungen.", "b": false}, {"t": "Sind Sie am Dienstag nicht zu Hause? Geben Sie dann bitte Ihren Schlüssel beim Nachbarn oder bei der Hausverwaltung ab.", "b": false}, {"t": "Vielen Dank.", "b": false}], "before": 3, "cap": "An der Haustür"}, {"paragraphs": [{"t": "Dr. med. Weier", "b": true}, {"t": "Arzt für Allgemeinmedizin", "b": false}, {"t": "Sprechstunden", "b": false}, {"t": "Montag bis Freitag 8 – 11 Uhr und 15 – 18 Uhr", "b": false}, {"t": "Mittwoch 8 – 12 Uhr", "b": false}, {"t": "auch nach Vereinbarung", "b": false}], "before": 4, "cap": "An der Tür der Arztpraxis"}, {"paragraphs": [{"t": "Ziehen Sie eine Nummer und nehmen Sie bitte Platz.", "b": false}, {"t": "Sie werden dann zu Ihrem Schalter aufgerufen.", "b": false}], "before": 5, "cap": "Im Bürgerbüro"}, {"paragraphs": [{"t": "WIR ZIEHEN UM!", "b": true}, {"t": "Die Bäckerei KOHLHAMMER finden Sie ab nächster Woche in der Taunusstraße 12.", "b": false}], "before": 6, "cap": "An einer Bäckerei"}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 1, "stil": "schild"}'::jsonb, 33),
    ('sf1-01', 'Schreiben', 'Übung 1 — Sprachenschule Lingua', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Marco aus England, geboren am 15.06.1985 in London, möchte im September einen Deutschkurs in Deutschland machen. Er ist Anfänger. Er hat am Nachmittag Zeit. In der Schule hat er Französisch und Spanisch gelernt. Er bekommt ein Anmeldeformular von der Sprachschule Lingua.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sprachenschule Lingua", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Gonman"}, {"label": "Vorname", "blank": 1}, {"label": "Geburtsdatum", "val": "16.06.1985"}, {"label": "Geburtsort", "blank": 2}, {"label": "Muttersprache", "val": "Englisch"}, {"label": "andere Sprachen", "blank": 3}, {"label": "schon Deutsch gelernt?", "blank": 4}, {"label": "Tageszeit", "val": "Nachmittag"}, {"label": "Termin", "blank": 5}]}}'::jsonb, 34),
    ('sf1-02', 'Schreiben', 'Übung 2 — Suchen Sie neue Freunde', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Malte Rodriguez aus Spanien, geboren am 18. Juli 1982. Seit einem Jahr wohnt sie in Berlin. Sie ist Ärztin und arbeitet im Krankenhaus. Sie liest in der Freizeit Reiseführer im Buchklub Leseratte.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Suchen Sie neue Freunde", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Rodriguez"}, {"label": "Vorname", "val": "Malte"}, {"label": "Geburtsdatum", "blank": 1}, {"label": "Geburtsort", "val": "Madrid"}, {"label": "Muttersprache", "val": "Spanisch"}, {"label": "Wohnort", "blank": 2}, {"label": "Geschlecht", "blank": 3}, {"label": "Beruf", "blank": 4}, {"label": "Welche Bücher mögen Sie?", "blank": 5}]}}'::jsonb, 35),
    ('sf1-03', 'Schreiben', 'Übung 3 — Kindergarten Lichtblick', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre russischen Freunde Fiodor und Lana haben eine Tochter. Sie wollen ihre Tochter Anna im Kindergarten anmelden. Der Vater ist Student und er will Sportlehrer werden. Sie wollen ihre Tochter am Vormittag in den Kindergarten bringen, denn ihre Mutter muss am Vormittag zur Arbeit gehen. Anna soll im September in den Kindergarten gehen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Kindergarten Lichtblick", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Pjetrov"}, {"label": "Vorname des Kindes", "blank": 1}, {"label": "Geburtsdatum", "val": "24.02.2009"}, {"label": "Geburtsort", "val": "Moskau"}, {"label": "Muttersprache", "blank": 2}, {"label": "Eintrittstermin", "blank": 3}, {"label": "Alter des Kindes", "val": "5 Jahre"}, {"label": "Beruf des Vaters", "blank": 4}, {"label": "Zeit", "blank": 5}]}}'::jsonb, 36),
    ('sf1-04', 'Schreiben', 'Übung 4 — Die besten Kurse in Hamburg', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Paola Pini aus Mondenah will nächstes Jahr von 18 bis 31 Oktober in Hamburg einen Exporthandelkurs besuchen. Sie sucht ein Angebot für Übernachtung mit dem Frühstück. Es soll nicht so teuer sein.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Die besten Kurse in Hamburg", "subtitle": "Anmeldung", "rows": [{"label": "Nachname, Vorname", "val": "Pini Paola"}, {"label": "Kurs", "blank": 1}, {"label": "Dauer des Kurses", "blank": 2}, {"label": "Bitte ankreuzen (Zimmer)", "blank": 3}, {"label": "Bitte ankreuzen (Frühstück)", "blank": 4}, {"label": "Wohnort", "blank": 5}]}}'::jsonb, 37),
    ('sf1-05', 'Schreiben', 'Übung 5 — Blumen für Ihre Liebsten', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Kollege Igor Schwerti möchte seiner Mutter Elena Blumen mit einer Geburtstagskarte schicken. Sie hat am Samstag 20.10 Geburtstag. Sie wohnt in den 7. Stock, Ludwigsstr. 8, 14193 Berlin. Seine Mutter ist erst um 14 Uhr zu Hause.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Blumen für Ihre Liebsten", "subtitle": "", "rows": [{"label": "Name, Vorname", "val": "Schwerti,", "blank": 1}, {"label": "Straße / Hausnummer", "val": "Ludwigsstr. 8"}, {"label": "Wohnort", "val": "14193", "blank": 2}, {"label": "Stock", "blank": 3}, {"label": "Geburtstag", "blank": 4}, {"label": "Zeit", "blank": 5}, {"label": "Zahlung", "val": "Kreditkarte (X)"}]}}'::jsonb, 38),
    ('sf1-06', 'Schreiben', 'Übung 6 — Nachhilfeunterricht für Kinder', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Antonio Verdi möchte seine Kinder (Paula 12 und Pietro 8) bei der Stundenhilfe anmelden. Die Familie ist seit drei Monaten in Deutschland. Beide Kinder brauchen Hilfe bei den Hausaufgaben. Die Tochter Paula in Englisch, der Sohn in Deutsch. Antonio möchte jeden Monat das Geld überweisen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Nachhilfeunterricht für Kinder", "subtitle": "Anmeldung", "rows": [{"label": "Kind 1 — Nachname, Vorname", "val": "Verdi, Paula"}, {"label": "Alter", "blank": 1}, {"label": "Hilfe in?", "blank": 2}, {"label": "Kind 2 — Nachname, Vorname", "val": "Verdi,", "blank": 3}, {"label": "Alter", "val": "8 Jahre"}, {"label": "Hilfe in?", "blank": 4}, {"label": "Zahlung", "blank": 5}]}}'::jsonb, 39),
    ('sf1-07', 'Schreiben', 'Übung 7 — Reise.com', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Kollege, Markus Schneider macht mit seiner Frau und seinen 3 Töchter (5, 7 und 11 Jahre alt) Urlaub in Spanien. Im Reisebüro bucht er für den nächsten Montag eine Schifffahrt nach Ibiza. Herr Schneider möchte mit der Kreditkarte bezahlen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Buchen Sie hier Ihren Urlaub, Reise.com", "subtitle": "Anmeldung", "rows": [{"label": "Nachname, Vorname", "val": "Schneider, Markus"}, {"label": "Anzahl der Personen", "blank": 1}, {"label": "Davon Kinder", "blank": 2}, {"label": "Urlaubsort", "blank": 3}, {"label": "Bitte ankreuzen", "blank": 4}, {"label": "Zahlung", "blank": 5}]}}'::jsonb, 40),
    ('sf1-08', 'Schreiben', 'Übung 8 — Bodensee-Rundfahrt', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Eva Kadavy macht mit ihrem Mann und ihren beiden Söhnen (8 und 11 Jahre alt) Urlaub in Seeheim. Im Reisebüro bucht sie für den nächsten Sonntag eine Busfahrt um den Bodensee. Frau Kadavy hat keine Kreditkarte.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Bodensee-Rundfahrt", "subtitle": "Anmeldung", "rows": [{"label": "Familienname, Vorname", "val": "Kadavy, Eva"}, {"label": "Anzahl der Personen", "blank": 1}, {"label": "Davon Kinder", "blank": 2}, {"label": "Urlaubsadresse", "val": "Hotel Schönblick"}, {"label": "Straße, Hausnummer", "val": "Burgstraße 34"}, {"label": "PLZ, Urlaubsort", "val": "78014", "blank": 3}, {"label": "Zahlungsweise", "blank": 4}, {"label": "Reisetermin", "blank": 5}]}}'::jsonb, 41),
    ('sf1-09', 'Schreiben', 'Übung 9 — Sportclub von 1896', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Munir Kassem kommt aus Ägypten und wohnt jetzt in Hamburg. Er ist 35 Jahre alt und von Beruf Arzt. In seiner Freizeit will er in einem Verein Fußball spielen. Bezahlen will er mit Kreditkarte.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sportclub von 1896", "subtitle": "Anmeldung", "rows": [{"label": "Name, Vorname", "val": "Kassem, Munir"}, {"label": "Straße / Hausnummer", "val": "Mundsburger Damm 29"}, {"label": "Wohnort", "val": "22087", "blank": 1}, {"label": "Telefon", "val": "020 / 299 11 45"}, {"label": "E-Mail", "val": "kassem24@web.de"}, {"label": "Beruf", "blank": 2}, {"label": "Alter", "blank": 3}, {"label": "Sport", "blank": 4}, {"label": "Zahlung", "blank": 5}]}}'::jsonb, 42),
    ('sf1-10', 'Schreiben', 'Übung 10 — Sprachschule NEWbornSCHOOL', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Yvonne Legrand aus Frankreich, geboren am 17.4.1993 in Lyon, möchte vom 1. bis zum 28. August einen Deutschkurs in Deutschland besuchen. Sie hat schon sechs Monate Deutsch gelernt. Sie hat am Vormittag Zeit. In der Schule hat sie Englisch gelernt.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sprachschule NEWbornSCHOOL", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Legrand"}, {"label": "Vorname", "val": "Yvonne"}, {"label": "Geburtsdatum", "val": "17.4.1993"}, {"label": "Geburtsort", "blank": 1}, {"label": "Muttersprache", "val": "Französisch"}, {"label": "Andere Sprachen", "blank": 2}, {"label": "Schon Deutsch gelernt?", "val": "ja"}, {"label": "Wie lange?", "blank": 3}, {"label": "Kurstermin", "blank": 4}, {"label": "Kurszeit", "blank": 5}]}}'::jsonb, 43),
    ('sf1-11', 'Schreiben', 'Übung 11 — Patienteninformation', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Vladimir Serjakov, 30 Jahre alt, kommt aus Sankt Petersburg in Russland und lebt seit einem Monat in Hamburg. Er hat eine neue Stelle bei TUI als Reiseleiter. Seit gestern hat er 39 Grad Fieber. Heute geht er zum Arzt.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Dr. Arnold Friedrich", "subtitle": "Patienteninformation", "rows": [{"label": "Name, Vorname", "val": "Serjakov, Vladimir"}, {"label": "Telefon", "val": "040 / 456 78 89"}, {"label": "Straße, Hausnummer", "val": "August-Bebel-Str. 22"}, {"label": "Postleitzahl, Wohnort", "val": "20969", "blank": 1}, {"label": "Alter", "blank": 2}, {"label": "Krankenkasse", "val": "AOK"}, {"label": "Beruf", "blank": 3}, {"label": "Seit wann sind Sie krank?", "blank": 4}, {"label": "Was fehlt Ihnen?", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 44),
    ('sf1-12', 'Schreiben', 'Übung 12 — Ferienwohnung', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Paolo Pellizzari aus Turin möchte mit seiner Familie (Ehefrau, drei Kinder, 2–7 Jahre alt) an der Ostsee Urlaub machen. Paolo hat drei Wochen Urlaub, vom 25.6. bis zum 15.7. Er sucht eine ruhige Wohnung am Meer, zwei Schlafzimmer, Wohnraum mit Küche, Bad. Paolo will mit dem Auto nach Deutschland kommen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Ferienwohnung am Meer", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Pellizzari"}, {"label": "Vorname", "val": "Paolo"}, {"label": "Anzahl der Personen", "blank": 1}, {"label": "davon Kinder", "blank": 2}, {"label": "Alter der Kinder", "val": "2–7"}, {"label": "Wie viele Schlafzimmer?", "val": "2"}, {"label": "Brauchen Sie eine Küche?", "blank": 3}, {"label": "Anreise", "val": "25. Juni"}, {"label": "Abreise", "blank": 4}, {"label": "Wie reisen Sie an?", "blank": 5}]}}'::jsonb, 45),
    ('sf1-13', 'Schreiben', 'Übung 13 — Buchbestellung', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Eleni Karamanlis möchte das Buch Pluspunkt Deutsch A1 im Internet bestellen. Sie hat keine Kreditkarte. Sie wohnt in der Berliner Straße 29 in Offenbach. Sie ist am 2. März 1980 geboren.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Buchbestellung", "subtitle": "", "rows": [{"label": "Name", "val": "Karamanlis"}, {"label": "Vorname", "val": "Eleni"}, {"label": "Straße", "blank": 1}, {"label": "PLZ / Ort", "val": "63067", "blank": 2}, {"label": "Geburtsdatum", "blank": 3}, {"label": "Bestellung", "blank": 4}, {"label": "Zahlungsweise", "blank": 5}]}}'::jsonb, 46),
    ('sf1-14', 'Schreiben', 'Übung 14 — Hotel Seeblick', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund, Julian Kirkpatrick, möchte im Hotel Seeblick in Cuxhaven ein Zimmer für sich und seine Frau vom 3.–8. Juni reservieren. Sie möchten nicht im Hotel frühstücken. Er möchte gern einen Fernseher im Zimmer haben und zwei Fahrräder mieten. Julian wohnt in Berlin.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Hotel Seeblick – Cuxhaven", "subtitle": "Reservierung", "rows": [{"label": "Name", "val": "Kirkpatrick"}, {"label": "Vorname", "val": "Julian"}, {"label": "Straße", "val": "Urbanstraße 12"}, {"label": "PLZ / Ort", "val": "10961", "blank": 1}, {"label": "Anreise", "val": "3. Juni"}, {"label": "Abreise", "blank": 2}, {"label": "Zimmer", "blank": 3}, {"label": "Frühstück", "blank": 4}, {"label": "Besondere Wünsche", "blank": 5}]}}'::jsonb, 47),
    ('sf1-15', 'Schreiben', 'Übung 15 — Sportverein TGB', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin, Kristina Pinnow, möchte ihren Sohn Oleg beim Sportverein TGB anmelden. Oleg ist 12 Jahre alt und möchte Fußball spielen. Familie Pinnow wohnt in 60385 Frankfurt, in der Leibnizstraße 35. Frau Pinnow möchte den Mitgliedsbeitrag alle drei Monate überweisen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sportverein TGB", "subtitle": "Anmeldung", "rows": [{"label": "Name des Kindes", "val": "Pinnow"}, {"label": "Vorname des Kindes", "blank": 1}, {"label": "Straße", "val": "Leibnizstraße 35"}, {"label": "PLZ / Ort", "val": "60385 Frankfurt"}, {"label": "Alter", "val": "12 Jahre"}, {"label": "Geschlecht", "blank": 2}, {"label": "Interessen", "blank": 3}, {"label": "Monatsbeitrag", "blank": 4}, {"label": "Zahlungsweise", "blank": 5}]}}'::jsonb, 48),
    ('sf1-16', 'Schreiben', 'Übung 16 — Anmeldung Sprachzentrum', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund, Juan Rodriguez, geboren am 12.10.1985, möchte einen Deutschkurs an der Volkshochschule machen. Er ist kein Anfänger, er hat schon die A1-Prüfung gemacht. Er ist Taxifahrer von Beruf und arbeitet abends. Er möchte vormittags einen Kurs besuchen. Juan wohnt in München, in der Danklstraße 15. Die Postleitzahl ist 81371.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Anmeldung – Sprachzentrum", "subtitle": "", "rows": [{"label": "Familienname", "val": "Rodriguez"}, {"label": "Vorname", "val": "Juan"}, {"label": "Postleitzahl, Wohnort", "blank": 1}, {"label": "Straße, Hausnummer", "blank": 2}, {"label": "Telefon", "val": "089 / 2935546"}, {"label": "Beruf", "blank": 3}, {"label": "Kurs / Kursnummer", "blank": 4}, {"label": "Termin", "blank": 5}]}}'::jsonb, 49),
    ('sf1-17', 'Schreiben', 'Übung 17 — Sportverein TUS Neustadt', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Alberto Gonzalez möchte sich in einem Sportverein anmelden. Er ist 30 Jahre alt, seine Hobbys sind Schwimmen und Ballspiele. Er möchte ab sofort in den Sportverein. Er hat keine Kreditkarte. Heute ist der 1. Dezember.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sportverein TUS – Neustadt", "subtitle": "Anmeldung", "rows": [{"label": "Familienname", "val": "Gonzalez"}, {"label": "Vorname", "val": "Alberto"}, {"label": "Straße, Hausnummer", "val": "Aachener Straße 12"}, {"label": "Postleitzahl, Wohnort", "val": "50567 Köln"}, {"label": "Alter", "blank": 1}, {"label": "Geschlecht", "blank": 2}, {"label": "Interessen / Sportarten", "blank": 3}, {"label": "Zahlungsweise", "blank": 4}, {"label": "Ab wann wollen Sie beim Verein mitmachen?", "val": "ab", "blank": 5}]}}'::jsonb, 50),
    ('sf1-18', 'Schreiben', 'Übung 18 — Online-Versand Prado', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Bekannter Sergej Brodsky möchte online zwei Jeans Modell Prado 511 in Schwarz bestellen. Er hat die Größe 34/32 und möchte mit Rechnung bezahlen. Er wohnt in Frankfurt, in der Dahlmannstraße 15, die Postleitzahl ist 60385.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Online-Versand Prado – Jeans für alle", "subtitle": "Bestellung", "rows": [{"label": "Familienname", "val": "Brodsky"}, {"label": "Vorname", "val": "Sergej"}, {"label": "Straße, Hausnummer", "blank": 1}, {"label": "Postleitzahl, Wohnort", "blank": 2}, {"label": "Bestellung: Jeans, Prado 511 — Menge", "val": "2"}, {"label": "Farbe", "blank": 3}, {"label": "Größe", "blank": 4}, {"label": "Mein Zahlungswunsch", "blank": 5}]}}'::jsonb, 51),
    ('sf1-19', 'Schreiben', 'Übung 19 — Ticket Servis', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Ola aus Nairobi in Kenia, ist mit ihrer Familie neu in Frankfurt am Main. Sie hat ihren Wohnsitz in der Gartenstraße 23. Sie möchte eine Reise machen und für ihren Ehemann und ihre beiden Töchter eine Gruppenkarte ab dem 01.02.2004 kaufen. Sie möchte für die Karte Geld überweisen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Ticket Servis", "subtitle": "", "rows": [{"label": "Name, Vorname", "val": "Rafi, Ola"}, {"label": "Karte", "val": "Gruppenkarte"}, {"label": "Straße, Hausnummer", "val": "Gartenstraße", "blank": 1}, {"label": "PLZ / Ort", "val": "60311 /", "blank": 2}, {"label": "Anzahl der Personen", "blank": 3}, {"label": "Ab Monat", "blank": 4}, {"label": "Bezahlen", "blank": 5}]}}'::jsonb, 52),
    ('sf1-20', 'Schreiben', 'Übung 20 — Stadtführer Deutschland', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin She Yang aus Peking in China, möchte ab Juli am Wochenende wieder als Stadtführerin in Deutschland für chinesische Gruppen arbeiten. Sie spricht fließend Englisch und Chinesisch aber kein Deutsch. Sie hat noch kein Telefonanschluss.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Stadtführer Deutschland", "subtitle": "", "rows": [{"label": "Name, Vorname", "val": "Yang, She"}, {"label": "Ab wann?", "blank": 1}, {"label": "Sprachen", "blank": 2}, {"label": "Arbeitszeiten", "blank": 3}, {"label": "Haben Sie Berufskenntnisse als Stadtführer/in?", "blank": 4}, {"label": "Telefonnummer", "blank": 5}]}}'::jsonb, 53),
    ('sf1-21', 'Schreiben', 'Übung 21 — Mietvertrag', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund, Ahmet Monsef kommt aus Tehran aus dem Iran. Er ist nicht verheiratet. Seine Familie wohnt in München. Er möchte als Fahrer bei BMW in Deutschland arbeiten. Deshalb möchte er dort eine Wohnung mieten. Er kann monatlich fünfhundertfünfzig Euro Gebühren bezahlen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Mietvertrag", "subtitle": "Mieter", "rows": [{"label": "Name, Vorname", "val": "Monsef, Ahmet"}, {"label": "geboren am", "val": "21.12.1955"}, {"label": "Wohnort", "blank": 1}, {"label": "Familienstand", "blank": 2}, {"label": "Beruf", "blank": 3}, {"label": "Firma", "blank": 4}, {"label": "Miete", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 54),
    ('sf1-22', 'Schreiben', 'Übung 22 — Sprachschule Lingua', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin, Ayşe Yılmaz kommt aus Izmir aus der Türkei und hat dort schon etwas Deutsch gelernt. Sie ist jetzt mit ihrem Mann in Berlin. Sie arbeitet nicht. Sie möchte weiter Deutsch lernen. Der Kurs ist von 13 bis 17 Uhr.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sprachschule Lingua", "subtitle": "Kursteilnehmer", "rows": [{"label": "Name, Vorname", "val": "Yılmaz, Ayşe"}, {"label": "Geburtsort", "blank": 1}, {"label": "Familienstand", "blank": 2}, {"label": "PLZ / Wohnort", "val": "32431 /", "blank": 3}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "Anfänger", "blank": 4}, {"label": "Kurs", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 55),
    ('sf1-23', 'Schreiben', 'Übung 23 — Sprachkurs', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Paul kommt aus Puebla in Mexiko und wohnt in der Rosenstraße 22 in Eltville am Rhein. Er möchte in Deutschland von 9 bis 12 Uhr ein Kurs machen. Der Kurs beginnt am 01.06.2015. Er möchte das Geld per Internet überweisen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Sprachkurs", "subtitle": "Kursteilnehmer", "rows": [{"label": "Name, Vorname", "val": "Ramirez, Paul"}, {"label": "Straße, Hausnummer", "val": "Rosenstraße", "blank": 1}, {"label": "Wohnort", "blank": 2}, {"label": "Monat", "blank": 3}, {"label": "Uhrzeit", "blank": 4}, {"label": "Zahlungsweise", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 56),
    ('sf1-24', 'Schreiben', 'Übung 24 — Mietvertrag', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin, Elena Ramirez aus Lima in Peru, arbeitet als Lehrerin in Deutschland. Sie mietet eine Wohnung bei der Wohnbau GmbH in Stuttgart. Die Wohnung hat zwei Zimmer und einen Garten. Sie liegt in der Rosenstraße 17 und kostet 500 Euro im Monat.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Mietvertrag", "subtitle": "Mieter", "rows": [{"label": "Name, Vorname", "val": "Ramirez, Elena"}, {"label": "geboren am", "val": "21.12.1955"}, {"label": "in", "blank": 1}, {"label": "Beruf", "blank": 2}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "PLZ / Wohnort", "val": "30409 /", "blank": 3}, {"label": "Wohnung", "val": "2 Zimmer"}, {"label": "Garten", "blank": 4}, {"label": "Vermieter", "val": "Wohnbau GmbH"}, {"label": "Miete", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 57),
    ('sf1-25', 'Schreiben', 'Übung 25 — Kindergarten Uesen', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin, Nadja Petrow aus Moskau wohnt in 91207 Lauf. Sie ist eine Sportlehrerin von Beruf und hat einen Sohn. Ihr Sohn Alex ist 3 Jahre alt. Alex muss von 10 bis 12 Uhr den Kindergarten besuchen. Der Kindergarten beginnt ab Dezember.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Kindergarten Uesen", "subtitle": "", "rows": [{"label": "Name, Vorname", "val": "Petrow, Nadja"}, {"label": "Geburtsort", "blank": 1}, {"label": "Beruf", "blank": 2}, {"label": "PLZ / Stadt", "blank": 3}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "Beginn", "blank": 4}, {"label": "Zeit", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 58),
    ('sf1-26', 'Schreiben', 'Übung 26 — TUI Reisen GmbH', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund Tom, möchte mit seiner Julie und seinem Sohn Chris (8 Jahre alt), am 30.08 ein Ausflug in Stuttgart machen. Von dort wollen Sie zum Urlaub nach Heidelberg fahren.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "TUI Reisen GmbH", "subtitle": "Person", "rows": [{"label": "Name, Vorname", "val": "Müller, Tom"}, {"label": "Partnerin", "blank": 1}, {"label": "Alter der Kinder", "blank": 2}, {"label": "Termin", "blank": 3}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "Ausflugsort", "blank": 4}, {"label": "Urlaubsort", "blank": 5}, {"label": "Gebühren", "val": "350 Euro"}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 59),
    ('sf1-27', 'Schreiben', 'Übung 27 — Stadtführer Deutschland', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin Shelang wohnt in Hamburg. Sie möchte ab August bis Juli am Wochenende einen Kurs machen. Die Kursgebühren möchte sie über Internet überweisen.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Stadtführer Deutschland", "subtitle": "Person", "rows": [{"label": "Name, Vorname", "val": "Shelang"}, {"label": "Wohnort", "blank": 1}, {"label": "Ab Wann", "blank": 2}, {"label": "Bis Wann", "blank": 3}, {"label": "Tag", "blank": 4}, {"label": "Bezahlen", "blank": 5}]}}'::jsonb, 60),
    ('sf1-28', 'Schreiben', 'Übung 28 — Deutsche Bahn AG', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihre Freundin, Tülay Ateş ist in Berlin und möchte mit ihrer Tochter Melissa nach Bielefeld fahren. Melissa ist 8 Jahre alt. Sie möchte auch einen Sitzplatz im Zug haben.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Deutsche Bahn AG", "subtitle": "Person", "rows": [{"label": "Name", "val": "Ateş"}, {"label": "Vorname", "val": "Tülay"}, {"label": "Anzahl der Personen", "blank": 1}, {"label": "Davon Kinder", "blank": 2}, {"label": "Straße und Hausnummer", "val": "Rosenstraße 17"}, {"label": "PLZ / Ort", "val": "10125 /", "blank": 3}, {"label": "Von Berlin nach", "blank": 4}, {"label": "Sitzplatz fürs Kind", "blank": 5}, {"label": "Gebühren", "val": "350 Euro"}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 61),
    ('sf1-29', 'Schreiben', 'Übung 29 — Kaufvertrag', 0, 'Lesen Sie den Text und ergänzen Sie die fünf fehlenden Informationen (1–5) im Formular.', 'formular', '{"passages": [{"paragraphs": [{"t": "Ihr Freund, Ali Hammad wohnt in München. Seine Freundin Agnes Kostmann hat Geburtstag und er möchte ihr ein Geschenk geben. Sie hat ihren Wohnsitz in Salzburg in Österreich.", "b": false}], "before": 0}], "maxPoints": 5, "availablePoints": 5, "missing": 0, "pointsPerItem": 1, "form": {"title": "Kaufvertrag", "subtitle": "Käufer", "rows": [{"label": "Absender", "val": "Hammad, Ali"}, {"label": "Adresse", "val": "Brienner Straße 21"}, {"label": "PLZ / Wohnort", "val": "54678 /", "blank": 1}, {"label": "Empfänger", "blank": 2}, {"label": "Name", "blank": 3}, {"label": "Stadt", "blank": 4}, {"label": "Land", "blank": 5}, {"label": "Datum", "val": "16.06."}]}}'::jsonb, 62),
    ('sf2-01', 'Schreiben', 'Übung 1 — Kühlschrank', 0, 'Sie bekommen am Dienstag einen neuen Kühlschrank. Sie müssen arbeiten. Schreiben Sie an Ihren Nachbarn Herrn Maier und bitten Sie um Hilfe. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Uhrzeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Schlüssel?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrter Herr Maier,\n\nam Dienstag bekomme ich einen neuen Kühlschrank, aber ich muss arbeiten. Deshalb schreibe ich Ihnen und bitte Sie um Hilfe. Der Kühlschrank wird um 8 Uhr geliefert. Können Sie bitte zu Hause sein? Meinen Schlüssel lege ich in Ihren Briefkasten.\n\nVielen Dank im Voraus.\nMit freundlichen Grüßen\nIhre Nachbarin"}'::jsonb, 63),
    ('sf2-02', 'Schreiben', 'Übung 2 — Arbeit als Verkäufer/in', 0, 'Sie suchen eine Arbeit als Verkäufer/Verkäuferin und lesen in der Zeitung eine Anzeige. Antworten Sie an den Supermarkt „cent". Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Informationen über sich?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Arbeitszeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nich habe Ihre Anzeige in der Zeitung gelesen und suche eine Arbeit als Verkäuferin. Deshalb schreibe ich Ihnen. Ich heiße Sara Ahmad, bin 25 Jahre alt und spreche Arabisch und ein bisschen Deutsch. Wann sind die Arbeitszeiten im Supermarkt?\n\nÜber eine Antwort freue ich mich sehr.\nMit freundlichen Grüßen\nSara Ahmad"}'::jsonb, 64),
    ('sf2-03', 'Schreiben', 'Übung 3 — Treffen absagen', 0, 'Ihre Freundin Nina möchte sich am Samstag mit Ihnen treffen, aber Sie können nicht. Schreiben Sie an Nina. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Treffen – wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Mitbringen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender (persönlicher) Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Nina,\n\nwie geht es dir? Leider kann ich mich am Samstag nicht mit dir treffen, weil ich arbeiten muss. Können wir uns am Sonntag um 18 Uhr treffen? Ich bringe einen Kuchen mit. Was möchtest du mitbringen?\n\nBis bald und liebe Grüße\nDeine Freundin"}'::jsonb, 65),
    ('sf2-04', 'Schreiben', 'Übung 4 — Neue Wohnung', 0, 'Sie möchten umziehen und suchen eine neue Wohnung. Sie haben eine Anzeige gelesen. Schreiben Sie an den Vermieter Herrn Mawat. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Wohnung sehen – wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Adresse?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrter Herr Mawat,\n\nich habe Ihre Anzeige im Internet gelesen und suche eine neue Wohnung, weil ich umziehen möchte. Wann kann ich die Wohnung besichtigen? Könnten Sie mir bitte auch die Adresse der Wohnung schicken?\n\nVielen Dank für Ihre Antwort.\nMit freundlichen Grüßen\nIhr(e) ..."}'::jsonb, 66),
    ('sf2-05', 'Schreiben', 'Übung 5 — Geburtstag', 0, 'Sie haben bald Geburtstag und möchten am Freitag feiern. Sie möchten Ihre Freunde Linda und Martin aus dem Sprachkurs einladen. Schreiben Sie an Linda und Martin. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Uhrzeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Musik?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender (persönlicher) Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Linda, lieber Martin,\n\nich habe bald Geburtstag und möchte am Freitag eine Party machen. Deshalb schreibe ich euch: Ich möchte euch gern einladen! Die Party beginnt um 19 Uhr bei mir zu Hause. Wir hören zusammen klassische Musik. Habt ihr Lust?\n\nIch freue mich auf euch.\nLiebe Grüße\nEuer Freund"}'::jsonb, 67),
    ('sf2-06', 'Schreiben', 'Übung 6 — Abschiedsparty', 0, 'Der Deutschkurs ist zu Ende. Sie machen eine Party und laden Ihre Lehrerin Frau Schmitz ein. Schreiben Sie an Frau Schmitz. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Party – wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Mitbringen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Frau Schmitz,\n\nunser Deutschkurs ist zu Ende und wir machen eine Party. Deshalb schreibe ich Ihnen: Wir möchten Sie gern einladen! Die Party findet am Samstag um 17 Uhr in der Schule statt. Könnten Sie bitte Getränke und eine Kamera mitbringen?\n\nWir freuen uns auf Sie.\nMit freundlichen Grüßen\nIhre Kursteilnehmer"}'::jsonb, 68),
    ('sf2-07', 'Schreiben', 'Übung 7 — Deutschkurs absagen', 0, 'Sie besuchen einen Deutschkurs und können nächsten Montag nicht zum Deutschkurs kommen. Schreiben Sie an Ihre Lehrerin Frau Schmidt. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Hausaufgaben?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Wieder da, wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Frau Schmidt,\n\nich schreibe Ihnen, weil ich nächsten Montag nicht zum Deutschkurs kommen kann. Ich bin leider sehr krank. Können Sie mir bitte die Hausaufgaben schicken? Ab nächstem Dienstag bin ich wieder da.\n\nMit freundlichen Grüßen\nIhre Kursteilnehmerin"}'::jsonb, 69),
    ('sf2-08', 'Schreiben', 'Übung 8 — Restaurant „Laura“', 0, 'Sie laden am Samstag 30 Personen zur Party ein und möchten im Restaurant essen. Schreiben Sie an das Restaurant „Laura“. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Welches Essen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Preis?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nam Samstag mache ich eine Party mit 30 Personen und möchte bei Ihnen im Restaurant essen. Deshalb schreibe ich Ihnen. Wir möchten gern Kebap und Salat essen. Wie viel kostet das Essen pro Person? Sind die Getränke inklusive?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 70),
    ('sf2-09', 'Schreiben', 'Übung 9 — Gästehaus Meier', 0, 'Sie fahren am nächsten Donnerstag nach Leipzig und brauchen ein Zimmer für eine Nacht. Schreiben Sie an das „Gästehaus Meier“. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Preis?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Ankunftszeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nam nächsten Donnerstag fahre ich nach Leipzig und brauche ein Zimmer für eine Nacht. Deshalb schreibe ich Ihnen. Wie viel kostet ein Einzelzimmer pro Nacht? Meine Ankunft ist um 16 Uhr.\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 71),
    ('sf2-10', 'Schreiben', 'Übung 10 — Schrank kaufen', 0, 'Sie suchen einen Schrank und lesen eine Anzeige im Internet. Schreiben Sie an den Verkäufer Herrn Teppert. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Preis?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Abholen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrter Herr Teppert,\n\nich habe Ihre Anzeige im Internet gelesen und möchte einen Schrank kaufen. Deshalb schreibe ich Ihnen. Wie viel kostet der Schrank? Wann kann ich den Schrank abholen?\n\nVielen Dank für Ihre Antwort.\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 72),
    ('sf2-11', 'Schreiben', 'Übung 11 — Mit Anna essen', 0, 'Sie haben Ihre Freundin Anna lange nicht gesehen und möchten mit ihr essen. Schreiben Sie an Anna. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Essen, wo?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Treffen, wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Anna,\n\nwie geht es dir? Wir haben uns lange nicht gesehen und ich möchte mit dir essen. Können wir uns am Freitag um 11 Uhr am Bahnhof treffen? Danach essen wir in einem Restaurant in der Nähe Pizza. Hast du Lust?\n\nLiebe Grüße\nAmani"}'::jsonb, 73),
    ('sf2-12', 'Schreiben', 'Übung 12 — Sofa kaufen', 0, 'Sie suchen ein Sofa und lesen in der Zeitung eine Anzeige. Antworten Sie an den Verkäufer. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Preis?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Abholen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nich habe Ihre Anzeige in der Zeitung gelesen und suche ein Sofa. Deshalb schreibe ich Ihnen. Wie viel kostet das Sofa? Wann kann ich das Sofa abholen?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 74),
    ('sf2-13', 'Schreiben', 'Übung 13 — Kochkurs', 0, 'Sie möchten bei der Kochschule Schmidt einen Kochkurs besuchen. Schreiben Sie an die „Kochschule Schmidt“. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Uhrzeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Preis?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nich möchte bei Ihnen einen Kochkurs machen, deshalb schreibe ich Ihnen. Wann findet der Kurs statt und wie sind die Kurszeiten? Wie viel kostet der Kochkurs?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 75),
    ('sf2-14', 'Schreiben', 'Übung 14 — Gratulieren', 0, 'Ihre Freundin Jasmin hat ein Baby bekommen. Sie möchten ihr gratulieren und sie zu Hause besuchen. Schreiben Sie an Jasmin. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Besuchen, wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Geschenk?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Jasmin,\n\nwie geht es dir? Zur Geburt deines Babys möchte ich dir herzlich gratulieren. Darf ich am Sonntagnachmittag vorbeikommen und dich besuchen? Ich möchte ein Geschenk für das Baby kaufen – was magst du?\n\nLiebe Grüße\nAmani"}'::jsonb, 76),
    ('sf2-15', 'Schreiben', 'Übung 15 — Einladung zur Hochzeit', 0, 'Ihr Freund Roland hat Sie zu seiner Hochzeit nach Bonn eingeladen. Schreiben Sie eine E-Mail an ihn. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Danke für die Einladung.", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Ihre Ankunft mit dem Zug: 17. Mai, 15:26 Uhr.", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Bitte: ein Zimmer für drei Nächte bestellen.", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Lieber Roland,\n\nvielen Dank für die Einladung zu deiner Hochzeit! Ich freue mich sehr. Ich komme am 17. Mai um 15:26 Uhr mit dem Zug in Bonn an. Kannst du mir bitte ein Hotelzimmer für drei Nächte reservieren?\n\nLiebe Grüße\nAmani"}'::jsonb, 77),
    ('sf2-16', 'Schreiben', 'Übung 16 — Besuch, nicht zu Hause', 0, 'Ihre Freundin Lina möchte Sie besuchen, aber Sie sind nicht zu Hause. Schreiben Sie an Lina. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Entschuldigen Sie sich.", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Sie muss die Linie 18 nehmen.", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Ihr Mann ist auch zu Hause.", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Lina,\n\nwie geht es dir? Ich möchte mich bei dir entschuldigen, weil ich nicht zu Hause bin. Du kannst mich gern besuchen. Nimm bitte die Linie 18, wir wohnen ganz in der Nähe. Mein Mann ist zu Hause und wartet auf dich.\n\nLiebe Grüße\nAmani"}'::jsonb, 78),
    ('sf2-17', 'Schreiben', 'Übung 17 — Familienfest', 0, 'Sie möchten am 15. August ein Familienfest mit hundert Personen feiern und brauchen einen großen Raum. Schreiben Sie an das Hotel „Kaiser Wilhelm“. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Essen, Preis?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Raum frei?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nam 15. August möchte ich ein Familienfest mit hundert Personen feiern und brauche einen großen Raum. Deshalb schreibe ich Ihnen. Wie viel kostet das Essen pro Person? Haben Sie an diesem Tag einen großen Raum frei?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 79),
    ('sf2-18', 'Schreiben', 'Übung 18 — Umzug, Hilfe', 0, 'Sie ziehen in die Berliner Straße 11 und brauchen Hilfe von Ihrem Freund. Schreiben Sie an Ihren Freund. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Treffen, wann?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Das Auto?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Lieber Johannes,\n\nwie geht es dir? Ich möchte in die Berliner Straße 11 umziehen und brauche deine Hilfe. Kannst du mir am nächsten Sonntag von 11 bis 15 Uhr helfen? Und kannst du bitte auch dein Auto mitbringen?\n\nLiebe Grüße\nAmani"}'::jsonb, 80),
    ('sf2-19', 'Schreiben', 'Übung 19 — Auto kaufen', 0, 'Sie suchen ein Auto und lesen im Internet eine Anzeige. Schreiben Sie an den Verkäufer. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Wie viele Personen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Wann sehen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nich habe Ihre Anzeige im Internet gelesen und möchte das Auto kaufen. Deshalb schreibe ich Ihnen. Für wie viele Personen ist das Auto? Wann kann ich das Auto sehen?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 81),
    ('sf2-20', 'Schreiben', 'Übung 20 — Geburtstag feiern', 0, 'Sie möchten Ihren Geburtstag feiern und Ihre Freunde Susanna und Paul einladen. Schreiben Sie an Susanna und Paul. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Tag und Uhrzeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Kommen, wie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Liebe Susanna, lieber Paul,\n\nwie geht es euch? Ich habe bald Geburtstag und möchte eine Party machen. Ich möchte euch gern einladen! Die Party findet am Sonntag um 19 Uhr im Restaurant statt. Könnt ihr mit dem Taxi kommen?\n\nLiebe Grüße\nAmani"}'::jsonb, 82),
    ('sf2-21', 'Schreiben', 'Übung 21 — Geburtstag im Büro', 0, 'Ihr neuer Kollege Herr Jensch hat Sie am Dienstag um 15 Uhr zu seiner Geburtstagsfeier im Büro eingeladen. Schreiben Sie an Herrn Jensch. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Später kommen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Helfen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Lieber Herr Jensch,\n\nvielen Dank für Ihre Einladung! Leider komme ich etwas später: Am Dienstag um 14 Uhr muss ich zum Arzt gehen. Um 15:30 Uhr kann ich zu Ihrer Feier ins Büro kommen. Kann ich Ihnen helfen? Ich bringe gern einen Kuchen mit.\n\nLiebe Grüße\nAmani"}'::jsonb, 83),
    ('sf2-22', 'Schreiben', 'Übung 22 — Computerkurs', 0, 'Sie möchten einen Computerkurs bei der Firma „Profil“ machen. Schreiben Sie an die Firma „Profil“. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Preis?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Uhrzeit?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nich möchte bei Ihnen einen Computerkurs machen, deshalb schreibe ich Ihnen. Wie viel kostet der Kurs? Wann findet der Kurs statt?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 84),
    ('sf2-23', 'Schreiben', 'Übung 23 — Fahrradausflug', 0, 'Sie möchten mit Ihrem Freund Peter am Sonntag einen Ausflug mit dem Fahrrad machen. Schreiben Sie an Peter. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Wohin fahren?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Wo treffen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Lieber Peter,\n\nwie geht es dir? Ich möchte am Sonntag gern einen Ausflug mit dem Fahrrad machen. Wir können mit dem Fahrrad zum Strand fahren. Treffen wir uns am Sonntag bei mir zu Hause?\n\nLiebe Grüße\nAmani"}'::jsonb, 85),
    ('sf2-24', 'Schreiben', 'Übung 24 — Urlaub in München', 0, 'Sie möchten im Sommer in München Urlaub machen. Schreiben Sie an die Touristeninformation. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Günstiges Hotel?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Sehenswürdigkeiten?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nich möchte im Sommer in München Urlaub machen, deshalb schreibe ich Ihnen. Können Sie mir Informationen über ein günstiges Hotel schicken? Was sind die Sehenswürdigkeiten in München?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 86),
    ('sf2-25', 'Schreiben', 'Übung 25 — Termin absagen', 0, 'Sie sind krank und können nicht nach Frankfurt zu einem Termin mit Herrn Bauer kommen. Schreiben Sie an Herrn Bauer. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Entschuldigung.", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Vorschlag: neuer Termin?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrter Herr Bauer,\n\nich hoffe, es geht Ihnen gut. Ich möchte mich entschuldigen: Leider kann ich nicht nach Frankfurt zu unserem Termin kommen, weil ich krank bin. Können wir uns am Samstag um 13 Uhr treffen?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 87),
    ('sf2-26', 'Schreiben', 'Übung 26 — Hotel Leonardo', 0, 'Sie möchten mit Ihrer Familie im Hotel Leonardo übernachten. Schreiben Sie an das Hotel. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Wie viele Leute kommen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Essen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nam Wochenende möchte ich mit meiner Familie in Ihrem Hotel übernachten, deshalb schreibe ich Ihnen. Ich komme mit fünf Personen. Was kann man in Ihrem Hotel essen? Gibt es arabisches Essen?\n\nMit freundlichen Grüßen\nAmani Kanaan"}'::jsonb, 88),
    ('sf2-27', 'Schreiben', 'Übung 27 — Dresden besuchen', 0, 'Sie möchten im August Dresden besuchen. Schreiben Sie an die Touristeninformation. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Warum schreiben Sie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Kulturprogramm (Film, Museen)?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Hoteladressen?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Sehr geehrte Damen und Herren,\n\nich möchte im August nach Dresden fahren. Deshalb möchte ich mich informieren, ob es in Dresden ein Kulturprogramm (Filme, Museen) gibt. Können Sie mir bitte auch Hoteladressen schicken?\n\nVielen Dank und freundliche Grüße\nAmani Kanaan"}'::jsonb, 89),
    ('sf2-28', 'Schreiben', 'Übung 28 — E-Mail an Jan', 0, 'Ihr Freund Jan hat Ihnen geschrieben: „Hallo, viele Grüße aus Sindelfingen! Ich bin in den Ferien bei meiner Oma, und ich finde es total langweilig. Hier kann man so wenig machen, und ich kenne auch niemanden. Was machst du denn so in den Ferien? Und wie geht es deiner Familie? Bitte schreib mir bald! Jan.“ Antworten Sie Jan. Schreiben Sie zu jedem Punkt ein bis zwei Sätze (ca. 30 Wörter).', 'writing', '{"criteria": [{"title": "Inhaltspunkt 1", "hint": "Reagieren Sie auf Jans Nachricht.", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 2", "hint": "Was machen Sie in den Ferien?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Inhaltspunkt 3", "hint": "Wie geht es Ihrer Familie?", "levels": [{"key": "A", "label": "vollständig und verständlich bearbeitet", "points": 3}, {"key": "B", "label": "nur teilweise oder mit sinnstörenden Fehlern", "points": 1.5}, {"key": "C", "label": "nicht bearbeitet oder unverständlich", "points": 0}]}, {"title": "Kommunikative Gestaltung", "hint": "Passende Anrede und Gruß, passender Stil.", "levels": [{"key": "A", "label": "Anrede und Gruß passend", "points": 1}, {"key": "B", "label": "Anrede oder Gruß fehlt / nur teilweise", "points": 0.5}, {"key": "C", "label": "keine passende Anrede und kein Gruß", "points": 0}]}], "maxPoints": 10, "availablePoints": 10, "missing": 0, "pointsPerItem": 10, "muster": "Lieber Jan,\n\nvielen Dank für deine E-Mail! Schade, dass es dir langweilig ist. In den Ferien bleibe ich zu Hause und treffe oft meine Freunde. Manchmal gehen wir schwimmen. Meiner Familie geht es gut. Komm uns doch bald besuchen!\n\nLiebe Grüße\nAmani"}'::jsonb, 90),
    ('sp1-01', 'Sprechen', 'Sich vorstellen', 0, null, 'vorstellen', '{"note": "Im Sprechen Teil 1 stellen Sie sich vor. Sprechen Sie über die Stichwörter. Danach stellt die Prüferin oder der Prüfer Ihnen ein bis zwei Fragen.", "availablePoints": 0, "missing": 0, "cards": [{"q": "Name?", "a": "Ich heiße … / Mein Name ist …"}, {"q": "Alter?", "a": "Ich bin … Jahre alt."}, {"q": "Land?", "a": "Ich komme aus …"}, {"q": "Wohnort?", "a": "Ich wohne in …"}, {"q": "Sprachen?", "a": "Ich spreche … und ein bisschen Deutsch."}, {"q": "Beruf?", "a": "Ich bin … von Beruf. / Ich arbeite als …"}, {"q": "Schule?", "a": "Ich besuche einen Deutschkurs. / Ich gehe in die Schule."}, {"q": "Hobby?", "a": "Mein Hobby ist … / In meiner Freizeit … ich gern."}], "fragen": [{"q": "Buchstabieren Sie bitte Ihren Namen.", "a": "Zum Beispiel: A – M – A – N – I."}, {"q": "Buchstabieren Sie bitte Ihren Familiennamen.", "a": "Mein Familienname ist … – ich buchstabiere: …"}, {"q": "Wie ist Ihre Telefonnummer?", "a": "Meine Nummer ist null – eins – sieben – drei – …"}, {"q": "Wie ist Ihre Adresse?", "a": "Ich wohne in der Berliner Straße 12."}, {"q": "Wie ist Ihre Postleitzahl?", "a": "Meine Postleitzahl ist eins – null – null – eins – fünf."}, {"q": "Wie lange lernen Sie schon Deutsch?", "a": "Ich lerne seit sechs Monaten Deutsch."}, {"q": "Wo lernen Sie Deutsch?", "a": "Ich lerne Deutsch in der Sprachschule."}, {"q": "Warum lernen Sie Deutsch?", "a": "Ich lerne Deutsch für meine Arbeit und für mein Leben hier."}, {"q": "Wie kommen Sie zum Kurs?", "a": "Ich komme mit dem Bus. / Ich komme zu Fuß."}, {"q": "Haben Sie Geschwister?", "a": "Ja, ich habe einen Bruder und eine Schwester. / Nein, ich bin Einzelkind."}, {"q": "Wie viele Personen sind in Ihrer Familie?", "a": "Wir sind vier Personen: meine Eltern, mein Bruder und ich."}, {"q": "Sind Sie verheiratet?", "a": "Ja, ich bin verheiratet. / Nein, ich bin ledig."}, {"q": "Haben Sie Kinder?", "a": "Ja, ich habe zwei Kinder. / Nein, ich habe keine Kin